/* =========================================================
   Pirenily tokens
   The only place colors live. Every component reads from here;
   add a token rather than hardcoding a hex or rgba.
   ========================================================= */
:root {
    color-scheme: dark;

    /* ----- Color ----- */
    --bg: #000;
    --accent: #1ca591;
    --accent-line: rgba(28, 165, 145, 0.55);
    --accent-wash: rgba(28, 165, 145, 0.06);
    --accent-glow: rgba(28, 165, 145, 0.35);
    --highlight: #fff;

    --title: #eee;
    --text-primary: #eaeaea;
    --lead: #bbb;
    --text-secondary: #9a9a9a;
    --text: #888;
    --text-tertiary: #7a7a7a;
    --text-dim: #555;

    /* Frosted pills and panels */
    --glass: rgba(255, 255, 255, 0.03);
    --glass-2: rgba(255, 255, 255, 0.04);
    --glass-3: rgba(255, 255, 255, 0.05);
    --glass-strong: rgba(255, 255, 255, 0.08);
    --hairline: rgba(255, 255, 255, 0.08);
    --hairline-strong: rgba(255, 255, 255, 0.22);
    --hairline-hover: rgba(255, 255, 255, 0.6);
    --dashed: rgba(255, 255, 255, 0.2);
    --pill-text: rgba(220, 220, 220, 0.75);
    --pill-text-on: rgba(255, 255, 255, 0.95);
    --mouse-line: rgba(255, 255, 255, 0.45);

    /* Project card */
    --card-border: rgba(180, 180, 180, 0.35);
    --card-bg: rgba(0, 0, 0, 0.25);
    --card-title: rgba(240, 240, 240, 0.95);
    --card-date: rgba(200, 200, 200, 0.55);
    --card-desc: rgba(200, 200, 200, 0.5);
    --card-placeholder: rgba(220, 220, 220, 0.55);
    --card-placeholder-line: rgba(200, 200, 200, 0.35);

    /* Overlays */
    --scrim: rgba(0, 0, 0, 0.82);
    --scrim-soft: rgba(0, 0, 0, 0.2);
    --panel-dark: rgba(0, 0, 0, 0.12);
    --shadow-ink: rgba(0, 0, 0, 0.55);

    /* Case-study facts panel and progress rail */
    --facts-tint: rgba(110, 145, 200, 0.18);
    --facts-tint-fade: rgba(110, 145, 200, 0.02);
    --rail-track: rgba(255, 255, 255, 0.2);
    --rail-ring: rgba(255, 255, 255, 0.4);
    --rail-hole: #000;
    --rail-core: rgba(255, 255, 255, 0.9);
    --rail-glow: rgba(28, 165, 145, 0.75);
    --rail-glow-soft: rgba(28, 165, 145, 0.3);

    /* ----- Type ----- */
    /* BHN Cinema isn't bundled (its license doesn't allow redistribution). Without it,
       display text falls back to Crimson Text. Bring your own with an @font-face named
       "BHN Cinema", or point --font-display at any font you like. */
    --font-display: "BHN Cinema", "Crimson Text", serif;
    --font-serif: "Crimson Text", serif;
    --fs-0: 0.5rem;
    --fs-1: 0.8rem;    /* small */
    --fs-2: 1rem;      /* body */
    --fs-3: 1.5rem;    /* subtitle */
    --fs-4: 2rem;      /* section title */
    --fs-5: 2.2rem;    /* hero title */
    --fs-display: clamp(2.2rem, 4.6vw, 3.4rem);
    --fs-heading: clamp(1.6rem, 3vw, 2.3rem);
    --fs-kicker: 0.7rem;
    --lh: 1.8;

    /* ----- Space ----- */
    --s-1: 0.25rem;
    --s-2: 0.5rem;
    --s-3: 0.75rem;
    --s-4: 1rem;
    --s-5: 1.5rem;
    --s-6: 2rem;
    --s-7: 3rem;

    /* ----- Shape ----- */
    --r-sm: 10px;
    --r-lg: 20px;
    --r-pill: 999px;

    /* Soft edges for unframed images: the picture dissolves into the black */
    --feather: 28px;
    --feather-mask:
        linear-gradient(to right, transparent, #000 var(--feather), #000 calc(100% - var(--feather)), transparent),
        linear-gradient(to bottom, transparent, #000 var(--feather), #000 calc(100% - var(--feather)), transparent);

    /* ----- Motion: one fast-out curve, three durations, no bounce ----- */
    --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
    --ease-wipe: cubic-bezier(0.7, 0, 0.2, 1);
    --dur-1: 150ms;
    --dur-2: 250ms;
    --dur-3: 450ms;
    --dur-glow: 600ms;
    --press: scale(0.97);
    --hover-blur: blur(1px);

    /* ----- Layout ----- */
    --rail-w: 11rem;
    --bp-tablet: 880px;  /* reference only; media queries can't read vars */
    --bp-phone: 666px;
}

/* =========================================================
   Base: black page, grey serif text, teal selection, quiet focus
   ========================================================= */
*,
*::before,
*::after {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    background: var(--bg);
    color: var(--text-dim);
    font-family: var(--font-serif);
    line-height: 1.5;
}

img {
    max-width: 100%;
}

::placeholder {
    color: var(--highlight);
    opacity: 1;
}

::selection {
    color: var(--accent);
    text-shadow: 0 0 5px var(--highlight);
    background-color: transparent;
}

/* Mouse clicks stay outline-free; keyboard users still see where they are */
:focus {
    outline: none;
}

:focus-visible {
    outline: 1px solid var(--accent);
    outline-offset: 3px;
}

/* Hover as a soft blur instead of a color change: the house motif */
.blur-hover {
    transition: filter var(--dur-1) var(--ease-out);
}

.blur-hover:hover,
.blur-hover:focus-visible {
    filter: var(--hover-blur);
}

/* Unframed image that dissolves into the black */
.feather {
    -webkit-mask-image: var(--feather-mask);
    -webkit-mask-composite: source-in;
    mask-image: var(--feather-mask);
    mask-composite: intersect;
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation: none !important;
        transition: none !important;
        scroll-behavior: auto !important;
    }
}

export function cx(...parts: Array<string | false | null | undefined>) {
    return parts.filter(Boolean).join(" ");
}

export const canHover = () =>
    typeof window !== "undefined" && window.matchMedia("(hover: hover)").matches;

import { forwardRef, type ButtonHTMLAttributes } from "react";
import { cx } from "./utils";
import "./button.css";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
    /** pill: hairline capsule. glass: frosted, a little brighter. ghost: text only. */
    variant?: "pill" | "glass" | "ghost";
    size?: "sm" | "md" | "lg";
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
    { variant = "pill", size = "md", className, type = "button", ...props },
    ref
) {
    return <button ref={ref} type={type} className={cx("pui-btn", `pui-btn--${variant}`, `pui-btn--${size}`, className)} {...props} />;
});

.pui-btn {
    font-family: var(--font-serif);
    font-style: italic;
    line-height: 1.2;
    color: var(--pill-text);
    background: none;
    border: 1px solid transparent;
    border-radius: var(--r-pill);
    cursor: pointer;
    transition: transform var(--dur-1) var(--ease-out), color var(--dur-1) var(--ease-out),
                border-color var(--dur-1) var(--ease-out), filter var(--dur-1) var(--ease-out);
}

.pui-btn:hover,
.pui-btn:focus-visible {
    color: var(--accent);
}

.pui-btn:active {
    transform: var(--press);
}

.pui-btn:disabled {
    opacity: 0.4;
    pointer-events: none;
}

.pui-btn--pill {
    background: var(--glass);
    border-color: var(--hairline-strong);
}

.pui-btn--glass {
    color: var(--pill-text-on);
    background: var(--glass-strong);
    border-color: var(--hairline-strong);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.pui-btn--ghost:hover,
.pui-btn--ghost:focus-visible {
    color: var(--pill-text-on);
    filter: var(--hover-blur);
}

.pui-btn--sm { padding: 0.2rem 0.75rem; font-size: 0.85rem; }
.pui-btn--md { padding: 0.45rem 1.1rem; font-size: 1rem; }
.pui-btn--lg { padding: 0.6rem 1.4rem; font-size: 1.15rem; }

import type { HTMLAttributes } from "react";
import { cx } from "./utils";
import "./tag.css";

export function Tag({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
    return <span className={cx("pui-tag", className)} {...props} />;
}

export function TagRow({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
    return <div className={cx("pui-tag-row", className)} {...props} />;
}

.pui-tag-row {
    display: flex;
    flex-wrap: wrap;
    gap: var(--s-2);
}

.pui-tag {
    padding: 0.2rem 0.65rem;
    font-family: var(--font-serif);
    font-style: italic;
    font-size: 0.75rem;
    line-height: 1.4;
    color: var(--pill-text);
    background: var(--glass);
    border: 1px solid var(--hairline-strong);
    border-radius: var(--r-pill);
    white-space: nowrap;
    user-select: none;
}

import type { HTMLAttributes } from "react";
import { cx } from "./utils";
import "./typography.css";

/** Small uppercase label for kickers, eyebrows and panel titles */
export function Kicker({ className, accent, ...props }: HTMLAttributes<HTMLParagraphElement> & { accent?: boolean }) {
    return <p className={cx("pui-kicker", accent && "pui-kicker--accent", className)} {...props} />;
}

/** Big BHN Cinema page heading */
export function PageTitle({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) {
    return <h1 className={cx("pui-page-title", className)} {...props} />;
}

/** The italic line under a page title */
export function PageNote({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) {
    return <p className={cx("pui-page-note", className)} {...props} />;
}

.pui-kicker {
    margin: 0;
    font-family: var(--font-serif);
    font-size: var(--fs-kicker);
    font-weight: 400;
    font-style: normal;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: var(--text-tertiary);
}

.pui-kicker--accent {
    color: var(--accent);
}

.pui-page-title {
    margin: 40px;
    font-family: var(--font-display);
    font-weight: normal;
    font-size: clamp(2.25rem, 4vw, 4rem);
    text-align: center;
    color: var(--highlight);
}

.pui-page-note {
    max-width: 90vw;
    margin: -1.5rem auto var(--s-5);
    font-family: var(--font-serif);
    font-style: italic;
    font-size: 0.9rem;
    line-height: var(--lh);
    text-align: center;
    color: var(--text);
}

.pui-page-note a {
    color: var(--lead);
    text-decoration: none;
    border-bottom: 1px solid var(--hairline);
    transition: filter var(--dur-1) var(--ease-out);
}

.pui-page-note a:hover {
    filter: var(--hover-blur);
}

"use client";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { cx } from "./utils";
import "./view-toggle.css";

export interface ViewToggleOption<T extends string = string> {
    value: T;
    label: ReactNode;
}

export interface ViewToggleProps<T extends string = string> {
    options: ViewToggleOption<T>[];
    value?: T;
    defaultValue?: T;
    onValueChange?: (value: T) => void;
    className?: string;
    "aria-label"?: string;
}

/** Segmented control: a frosted pill slides behind the active option */
export function ViewToggle<T extends string = string>({
    options, value, defaultValue, onValueChange, className, ...aria
}: ViewToggleProps<T>) {
    const [inner, setInner] = useState<T>(defaultValue ?? options[0]?.value);
    const current = value ?? inner;
    const root = useRef<HTMLDivElement>(null);
    const pill = useRef<HTMLSpanElement>(null);
    const animate = useRef(false);

    useLayoutEffect(() => {
        const el = root.current;
        const p = pill.current;
        if (!el || !p) return;
        const place = () => {
            const on = el.querySelector<HTMLElement>('[aria-pressed="true"]');
            if (!on) return;
            if (!animate.current) p.style.transition = "none";
            p.style.width = on.offsetWidth + "px";
            p.style.transform = `translateX(${on.offsetLeft}px)`;
            if (!animate.current) { void p.offsetWidth; p.style.transition = ""; }
        };
        place();
        animate.current = true;
        const ro = new ResizeObserver(() => { animate.current = false; place(); animate.current = true; });
        ro.observe(el);
        return () => ro.disconnect();
    }, [current, options.length]);

    function select(v: T) {
        if (value === undefined) setInner(v);
        onValueChange?.(v);
    }

    return (
        <div ref={root} role="group" className={cx("pui-view-toggle", className)} {...aria}>
            {options.map((o) => (
                <button
                    key={o.value}
                    type="button"
                    className="pui-view-btn"
                    aria-pressed={o.value === current}
                    onClick={() => select(o.value)}
                >
                    {o.label}
                </button>
            ))}
            <span ref={pill} className="pui-view-pill" aria-hidden="true" />
        </div>
    );
}

.pui-view-toggle {
    position: relative;
    display: flex;
    width: fit-content;
    padding: var(--s-1);
    font-family: var(--font-serif);
    font-style: italic;
    background: var(--glass);
    border: 1px solid var(--hairline);
    border-radius: var(--r-pill);
}

.pui-view-btn {
    position: relative;
    z-index: 1;
    padding: var(--s-1) var(--s-4);
    font: inherit;
    font-size: 1.05rem;
    color: var(--text);
    background: none;
    border: none;
    border-radius: var(--r-pill);
    cursor: pointer;
    transition: transform var(--dur-1) var(--ease-out), color var(--dur-1) var(--ease-out);
}

.pui-view-btn[aria-pressed="true"] {
    color: var(--title);
}

.pui-view-btn:hover,
.pui-view-btn:focus-visible {
    color: var(--accent);
}

.pui-view-btn:active {
    transform: var(--press);
}

.pui-view-pill {
    position: absolute;
    top: var(--s-1);
    bottom: var(--s-1);
    left: 0;
    background: var(--glass-strong);
    border: 1px solid var(--hairline-strong);
    border-radius: var(--r-pill);
    pointer-events: none;
    transition: transform var(--dur-2) var(--ease-out), width var(--dur-2) var(--ease-out);
}

"use client";
import { useState, type ReactNode } from "react";
import { cx } from "./utils";
import "./side-tabs.css";

export interface SideTabsProps<T extends string = string> {
    tabs: { value: T; label: ReactNode }[];
    value?: T;
    defaultValue?: T;
    onValueChange?: (value: T) => void;
    /** Fixed to the left edge of the screen (default) or inline */
    position?: "fixed" | "inline";
    /** When fixed: slide in from the edge (true) or stay tucked away (false) */
    show?: boolean;
    className?: string;
}

/** Capsules attached to the screen edge; they slide in, never fade */
export function SideTabs<T extends string = string>({
    tabs, value, defaultValue, onValueChange, position = "fixed", show = true, className,
}: SideTabsProps<T>) {
    const [inner, setInner] = useState<T>(defaultValue ?? tabs[0]?.value);
    const current = value ?? inner;

    return (
        <div className={cx("pui-side-tabs", `pui-side-tabs--${position}`, show && "is-shown", className)}>
            {tabs.map((t) => (
                <button
                    key={t.value}
                    type="button"
                    className="pui-side-tab"
                    aria-pressed={t.value === current}
                    onClick={() => {
                        if (value === undefined) setInner(t.value);
                        onValueChange?.(t.value);
                    }}
                >
                    {t.label}
                </button>
            ))}
        </div>
    );
}

.pui-side-tabs {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
}

.pui-side-tabs--fixed {
    position: fixed;
    left: 0;
    top: 50%;
    z-index: 40;
    transform: translateY(-50%) translateX(-110%);
    visibility: hidden;
    pointer-events: none;
    transition: transform var(--dur-3) var(--ease-out), visibility 0s linear var(--dur-3);
}

.pui-side-tabs--fixed.is-shown {
    transform: translateY(-50%) translateX(0);
    visibility: visible;
    pointer-events: auto;
    transition: transform var(--dur-3) var(--ease-out), visibility 0s;
}

.pui-side-tab {
    padding: 0.55rem 1.2rem 0.55rem 1rem;
    font-family: var(--font-serif);
    font-style: italic;
    font-size: 0.95rem;
    text-align: left;
    color: var(--pill-text);
    background: var(--glass);
    border: 1px solid var(--hairline-strong);
    border-left: none;
    border-radius: 0 var(--r-pill) var(--r-pill) 0;
    transform-origin: left center;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    cursor: pointer;
    transition: transform var(--dur-1) var(--ease-out), color var(--dur-1) var(--ease-out);
}

.pui-side-tab[aria-pressed="true"] {
    color: var(--pill-text-on);
    background: var(--glass-strong);
}

.pui-side-tab:hover,
.pui-side-tab:focus-visible {
    color: var(--accent);
}

.pui-side-tab:active {
    transform: var(--press);
}

"use client";
import { useId, useRef, useState, type ReactNode } from "react";
import { cx } from "./utils";
import "./accordion.css";

export interface AccordionProps {
    title: ReactNode;
    children: ReactNode;
    defaultOpen?: boolean;
    className?: string;
}

/** A receipt that folds away */
export function Accordion({ title, children, defaultOpen = false, className }: AccordionProps) {
    const [open, setOpen] = useState(defaultOpen);
    const [height, setHeight] = useState<number | "none">(defaultOpen ? "none" : 0);
    const panel = useRef<HTMLDivElement>(null);
    const id = useId();

    return (
        <div className={cx("pui-accordion", className)}>
            <button
                type="button"
                className="pui-acc-btn"
                aria-expanded={open}
                aria-controls={id}
                onClick={() => {
                    const next = !open;
                    setOpen(next);
                    setHeight(next ? panel.current?.scrollHeight ?? "none" : 0);
                }}
            >
                <span>{title}</span>
                <span className="pui-acc-chev" aria-hidden="true">⌄</span>
            </button>
            <div
                id={id}
                ref={panel}
                className="pui-acc-panel"
                style={{ maxHeight: height }}
            >
                <div className="pui-acc-inner">{children}</div>
            </div>
        </div>
    );
}

.pui-accordion {
    width: 100%;
    overflow: hidden;
    background: var(--panel-dark);
    border: 1px solid var(--hairline);
    border-radius: var(--r-lg);
}

.pui-accordion + .pui-accordion {
    margin-top: var(--s-3);
}

.pui-acc-btn {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--s-4);
    width: 100%;
    padding: 0.9rem var(--s-4);
    font-family: var(--font-serif);
    font-style: italic;
    font-size: 0.95rem;
    text-align: left;
    color: var(--title);
    background: transparent;
    border: none;
    cursor: pointer;
}

.pui-acc-chev {
    opacity: 0.7;
    transition: transform var(--dur-1) var(--ease-out);
}

.pui-acc-btn[aria-expanded="true"] .pui-acc-chev {
    transform: rotate(180deg);
}

.pui-acc-panel {
    overflow: hidden;
    border-top: 1px solid var(--hairline);
    transition: max-height var(--dur-3) var(--ease-out);
}

.pui-acc-inner {
    padding: var(--s-4);
    font-family: var(--font-serif);
    font-size: 0.9rem;
    line-height: var(--lh);
    color: var(--text);
}

import type { HTMLAttributes, ReactNode } from "react";
import { Tag } from "./tag";
import { cx } from "./utils";
import "./card.css";

export interface CardProps {
    title: ReactNode;
    /** Image URL. Leave out for a placeholder frame. */
    image?: string;
    imageAlt?: string;
    /** Text in the placeholder frame; an empty string gives a solid black frame */
    placeholder?: string;
    /** Crop the image to 16:9 so cards in a row line up */
    cover?: boolean;
    tags?: string[];
    subtitle?: ReactNode;
    date?: ReactNode;
    description?: ReactNode;
    /** Link cards blur on hover; cards without href stay still */
    href?: string;
    /** Opens in a new tab */
    external?: boolean;
    className?: string;
}

/** Screenshot on top, italic title with tag chips, subtitle + date, a one-line description */
export function Card({
    title, image, imageAlt = "", placeholder = "Coming soon", cover, tags = [],
    subtitle, date, description, href, external, className,
}: CardProps) {
    const body = (
        <>
            {image ? (
                <img className={cx("pui-card-img", cover && "pui-card-img--cover")} src={image} alt={imageAlt} loading="lazy" />
            ) : (
                <div className={cx("pui-card-img", "pui-card-placeholder", !placeholder && "pui-card-placeholder--blank")}>{placeholder}</div>
            )}
            <div className="pui-card-meta">
                <div className="pui-card-namebox">
                    <div className="pui-card-title">{title}</div>
                    <div className="pui-card-tags">{tags.map((t) => <Tag key={t}>{t}</Tag>)}</div>
                </div>
                <div className="pui-card-subrow">
                    <div className="pui-card-sub">{subtitle}</div>
                    {date && <div className="pui-card-date">{date}</div>}
                </div>
                {description && <div className="pui-card-desc">{description}</div>}
            </div>
        </>
    );

    if (href) {
        return (
            <a className={cx("pui-card", className)} href={href} {...(external ? { target: "_blank", rel: "noopener" } : {})}>
                {body}
            </a>
        );
    }
    return <div className={cx("pui-card", className)}>{body}</div>;
}

/** Two-up grid. Neighbouring cards share subgrid rows so they line up and end level. */
export function CardGrid({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
    return <div className={cx("pui-card-grid", className)} {...props} />;
}

.pui-card {
    display: block;
    overflow: hidden;
    text-decoration: none;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: var(--r-lg);
    backdrop-filter: blur(2px);
    transition: filter var(--dur-2) var(--ease-out), border-color var(--dur-2) var(--ease-out);
}

a.pui-card:hover,
a.pui-card:focus-visible {
    border-color: var(--hairline-hover);
    filter: var(--hover-blur);
}

.pui-card-img {
    display: block;
    width: 100%;
    height: auto;
}

.pui-card-img--cover {
    aspect-ratio: 16 / 9;
    object-fit: cover;
}

