import "./pop-layer.css";

// One fixed layer shared by every pop-up picture on the page. A picture shows at a
// random spot, instantly, and is gone the moment it's hidden. No fades.
let layer: HTMLDivElement | null = null;
let wanted: string | null = null;

function getLayer() {
    if (!layer || !layer.isConnected) {
        layer = document.createElement("div");
        layer.className = "pui-pop-layer";
        document.body.appendChild(layer);
    }
    return layer;
}

/** Pop `src` up somewhere on screen. width defaults to a random 180–320px. */
export function showPop(src: string, width?: number) {
    wanted = src;
    const img = new Image();
    img.onload = () => {
        if (wanted !== src) return; // hidden again before it loaded
        const w = Math.min(width ?? Math.round(180 + Math.random() * 140), innerWidth - 32);
        const h = (img.naturalHeight * w) / img.naturalWidth;
        img.className = "pui-pop";
        img.alt = "";
        img.style.width = w + "px";
        img.style.left = Math.round(Math.random() * Math.max(0, innerWidth - w)) + "px";
        img.style.top = Math.round(Math.random() * Math.max(0, innerHeight - h)) + "px";
        const l = getLayer();
        l.replaceChildren(img);
    };
    img.src = src;
}

export function hidePop() {
    wanted = null;
    layer?.replaceChildren();
}

export function currentPop() {
    return wanted;
}

.pui-pop-layer {
    position: fixed;
    inset: 0;
    z-index: 50;
    pointer-events: none;
}

.pui-pop {
    position: absolute;
    display: block;
    height: auto;
    border: 1px solid var(--hairline);
}

"use client";
import { cloneElement, useRef, type FocusEvent, type MouseEvent, type ReactElement } from "react";
import { canHover } from "./utils";
import { hidePop, showPop } from "./pop-layer";

type Handlers = {
    onMouseEnter?: (e: MouseEvent) => void;
    onMouseLeave?: (e: MouseEvent) => void;
    onFocus?: (e: FocusEvent) => void;
    onBlur?: (e: FocusEvent) => void;
};

export interface HoverPreviewProps {
    /** Picture URLs; each new hover shows a different one */
    images: string[];
    /** One element; it receives the hover and focus handlers */
    children: ReactElement<Handlers>;
}

const GRACE = 400;

/** Hovering (or tabbing onto) the child pops one of its pictures up at a random spot on screen */
export function HoverPreview({ images, children }: HoverPreviewProps) {
    const last = useRef(-1);
    const shown = useRef<string | null>(null);
    const leftAt = useRef(0);

    function enter() {
        if (!images.length || !canHover()) return;
        // brushing off the edge and straight back isn't a new hover: keep the same picture
        if (shown.current && Date.now() - leftAt.current < GRACE) return showPop(shown.current);
        let n = Math.floor(Math.random() * images.length);
        if (images.length > 1 && n === last.current) n = (n + 1) % images.length;
        last.current = n;
        shown.current = images[n];
        showPop(images[n]);
    }

    function leave() {
        leftAt.current = Date.now();
        hidePop();
    }

    const p = children.props;
    return cloneElement(children, {
        onMouseEnter: (e: MouseEvent) => { p.onMouseEnter?.(e); enter(); },
        onMouseLeave: (e: MouseEvent) => { p.onMouseLeave?.(e); leave(); },
        onFocus: (e: FocusEvent) => { p.onFocus?.(e); if ((e.target as HTMLElement).matches(":focus-visible")) enter(); },
        onBlur: (e: FocusEvent) => { p.onBlur?.(e); leave(); },
    });
}

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { canHover, cx } from "./utils";
import { currentPop, hidePop, showPop } from "./pop-layer";
import "./flip-card.css";

export interface FlipCardProps {
    /** The headshot on the front */
    front: string;
    frontAlt?: string;
    /** Small pictures on the back, each pops up when hovered (or tapped) */
    pictures: string[];
    /** Italic line under the pictures on the back */
    note?: ReactNode;
    className?: string;
}

/** Hover the front for a random picture; click to flip to a feathered grid of small ones */
export function FlipCard({ front, frontAlt = "", pictures, note, className }: FlipCardProps) {
    const [flipped, setFlipped] = useState(false);
    const last = useRef(-1);
    const hover = useRef(false);

    useEffect(() => {
        hover.current = canHover();
        if (hover.current) return;
        // Touch: a tap anywhere else puts the picture away
        const off = () => hidePop();
        document.addEventListener("click", off);
        return () => document.removeEventListener("click", off);
    }, []);

    function randomPicture() {
        if (pictures.length < 2) return pictures[0];
        let i = Math.floor(Math.random() * (pictures.length - 1));
        if (i >= last.current) i++;
        last.current = i;
        return pictures[i];
    }

    function flip() {
        hidePop();
        setFlipped((f) => !f);
    }

    return (
        <div
            className={cx("pui-flip", flipped && "is-flipped", className)}
            role="button"
            tabIndex={0}
            aria-pressed={flipped}
            aria-label="Flip to see more pictures"
            onClick={flip}
            onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); flip(); } }}
        >
            <div
                className="pui-flip-front"
                onMouseEnter={() => { if (hover.current && pictures.length) showPop(randomPicture(), 300); }}
                onMouseLeave={hidePop}
            >
                <img src={front} alt={frontAlt} />
            </div>
            <div className="pui-flip-back">
                {pictures.map((src) => (
                    <img
                        key={src}
                        className="pui-flip-thumb"
                        src={src}
                        alt=""
                        loading="lazy"
                        onMouseEnter={() => { if (hover.current) showPop(src, 300); }}
                        onMouseLeave={() => { if (hover.current) hidePop(); }}
                        onClick={(e) => {
                            e.stopPropagation();
                            if (!hover.current) currentPop() === src ? hidePop() : showPop(src, 300);
                        }}
                    />
                ))}
                {note && <p className="pui-flip-note">{note}</p>}
            </div>
        </div>
    );
}

.pui-flip {
    position: relative;
    width: min(300px, 100%);
    perspective: 1200px;
    cursor: pointer;
}

.pui-flip-front,
.pui-flip-back {
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transition: transform 700ms var(--ease-out);
}

.pui-flip-front img {
    display: block;
    width: 100%;
    opacity: 0.8;
    filter: grayscale(100%);
    -webkit-mask-image: var(--feather-mask);
    -webkit-mask-composite: source-in;
    mask-image: var(--feather-mask);
