"use client";
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { Tag, TagRow } from "./tag";
import { LightboxImage } from "./lightbox";
import { cx } from "./utils";
import "./case-study.css";

const slug = (s: string) => s.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export interface CaseStudyProps {
    children: ReactNode;
    backHref?: string;
    backLabel?: ReactNode;
    /** Sticky offset of the rail in px. By default it sticks where it starts, up to 128px down. */
    railTop?: number;
    className?: string;
}

/**
 * Sticky progress rail on the left, reading column on the right. Every CaseSection
 * is numbered and listed on the rail; the line fills ring to ring as you read and
 * the current ring glows. Below 1000px the rail hides.
 */
export function CaseStudy({ children, backHref, backLabel = "← Back", railTop, className }: CaseStudyProps) {
    const shell = useRef<HTMLDivElement>(null);
    const list = useRef<HTMLOListElement>(null);
    const [title, setTitle] = useState("");
    const [sections, setSections] = useState<{ id: string; label: string }[]>([]);
    const [current, setCurrent] = useState(-1);
    const [fill, setFill] = useState(0);

    // Collect the sections once they're in the DOM
    useIsoLayoutEffect(() => {
        const el = shell.current;
        if (!el) return;
        // Stick at the spot the rail starts in, so it never scrolls first; deep in a page, cap it
        const start = el.getBoundingClientRect().top + scrollY + parseFloat(getComputedStyle(el).paddingTop);
        el.style.setProperty("--rail-top", (railTop ?? Math.min(start, 128)) + "px");
        const hero = el.querySelector<HTMLElement>(".pui-cs-hero");
        setTitle(hero?.dataset.index ?? "");
        const found = Array.from(el.querySelectorAll<HTMLElement>("[data-index]"))
            .filter((s) => s !== hero)
            .map((s) => {
                s.id ||= slug(s.dataset.index!);
                return { id: s.id, label: s.dataset.index! };
            });
        setSections(found);
    }, [children, railTop]);

    useEffect(() => {
        if (!sections.length) return;
        const onScroll = () => {
            const line = scrollY + innerHeight * 0.35;
            const els = sections.map((s) => document.getElementById(s.id)!);
            const tops = els.map((s) => s.getBoundingClientRect().top + scrollY);
            const rings = Array.from(list.current?.querySelectorAll<HTMLLIElement>("li:not(.pui-cs-fill)") ?? []);
            const centers = rings.map((li) => li.offsetTop + li.offsetHeight / 2);
            let cur = -1;
            tops.forEach((t, i) => { if (t <= line) cur = i; });
            let y = centers[0] ?? 0;
            if (cur >= 0 && cur < tops.length - 1) {
                const t = Math.min(1, (line - tops[cur]) / (tops[cur + 1] - tops[cur]));
                y = centers[cur] + t * (centers[cur + 1] - centers[cur]);
            } else if (cur >= 0) {
                y = centers[cur];
            }
            setCurrent(cur);
            setFill(y - (centers[0] ?? 0));
        };
        onScroll();
        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll);
        return () => {
            window.removeEventListener("scroll", onScroll);
            window.removeEventListener("resize", onScroll);
        };
    }, [sections]);

    return (
        <div ref={shell} className={cx("pui-cs", className)}>
            <aside className="pui-cs-rail">
                {backHref && <a className="pui-cs-back" href={backHref}>{backLabel}</a>}
                <p className="pui-cs-kicker">Reading</p>
                <p className="pui-cs-rail-title">{title}</p>
                <ol ref={list} className="pui-cs-index" style={{ "--n": sections.length } as CSSProperties} aria-label="Sections">
                    <li className="pui-cs-fill" style={{ height: fill }} aria-hidden="true" />
                    {sections.map((s, i) => (
                        <li key={s.id}>
                            <a
                                href={`#${s.id}`}
                                className={cx(i === current && "is-current", i < current && "is-passed")}
                                aria-label={`${String(i + 1).padStart(2, "0")} ${s.label}`}
                            >
                                <span className="pui-cs-index-label">{s.label}</span>
                            </a>
                        </li>
                    ))}
                </ol>
            </aside>
            <article className="pui-cs-main">{children}</article>
        </div>
    );
}

export interface CaseHeroProps {
    title: ReactNode;
    /** Rail label; defaults to the title when it's plain text */
    index?: string;
    eyebrow?: ReactNode;
    /** Right-hand line, usually the dates */
    meta?: ReactNode;
    subtitle?: ReactNode;
    tags?: string[];
    /** The tinted meta grid: Role, Team, Timeline... */
    facts?: { label: ReactNode; values: ReactNode[] }[];
    /** Makes the title a link */
    href?: string;
}

export function CaseHero({ title, index, eyebrow = "Case study", meta, subtitle, tags, facts, href }: CaseHeroProps) {
    return (
        <header className="pui-cs-hero" data-index={index ?? (typeof title === "string" ? title : "")}>
            <div className="pui-cs-hero-top">
                <p className="pui-cs-kicker">{eyebrow}</p>
                {meta && <p className="pui-cs-kicker">{meta}</p>}
            </div>
            <h1 className="pui-cs-title">{href ? <a href={href} target="_blank" rel="noopener noreferrer">{title}</a> : title}</h1>
            {subtitle && <p className="pui-cs-sub">{subtitle}</p>}
            {tags && tags.length > 0 && <TagRow className="pui-cs-tags">{tags.map((t) => <Tag key={t}>{t}</Tag>)}</TagRow>}
            {facts && facts.length > 0 && (
                <dl className="pui-cs-facts">
                    {facts.map((f, i) => (
                        <div key={i}>
                            <dt className="pui-cs-kicker">{f.label}</dt>
                            {f.values.map((v, j) => <dd key={j}>{v}</dd>)}
                        </div>
                    ))}
                </dl>
            )}
        </header>
    );
}

export interface CaseSectionProps {
    /** Short name: the eyebrow and the rail label */
    heading: string;
    /** The big line under the eyebrow; defaults to the heading */
    lead?: ReactNode;
    /** Shorter rail label for long headings */
    index?: string;
    children?: ReactNode;
}

/** A numbered section. Numbers come from a CSS counter, in order. */
export function CaseSection({ heading, lead, index, children }: CaseSectionProps) {
    return (
        <section className="pui-cs-section" data-index={index ?? heading}>
            <p className="pui-cs-eyebrow"><span className="pui-cs-num" />{lead ? heading : null}</p>
            <h2 className="pui-cs-heading">{lead ?? heading}</h2>
            {children && <div className="pui-cs-prose">{children}</div>}
        </section>
    );
}

/** Media with an auto-numbered "Fig. 01" caption */
export function CaseFigure({ caption, children }: { caption?: ReactNode; children: ReactNode }) {
    return (
        <figure className="pui-cs-figure">
            {children}
            {caption && <figcaption className="pui-cs-caption">{caption}</figcaption>}
        </figure>
    );
}

export interface CaseMediaProps {
    src?: string;
    alt?: string;
    /** Open in the lightbox on click (default true) */
    zoom?: boolean;
    size?: "sm" | "md" | "lg";
    /** No src: a dashed frame with this text */
    placeholder?: string;
}

export function CaseMedia({ src, alt = "", zoom = true, size, placeholder = "Coming soon" }: CaseMediaProps) {
    if (!src) return <div className="pui-cs-media pui-cs-media--placeholder">{placeholder}</div>;
    return (
        <div className={cx("pui-cs-media", size && `pui-cs-media--${size}`)}>
            {zoom ? <LightboxImage src={src} alt={alt} loading="lazy" /> : <img src={src} alt={alt} loading="lazy" />}
        </div>
    );
}

/** Media side by side. flow: text column wider. pair: stays two-up on phones. */
export function CaseRow({ layout = "equal", children }: { layout?: "equal" | "pair" | "flow" | "3" | "quad"; children: ReactNode }) {
    return <div className={cx("pui-cs-row", `pui-cs-row--${layout}`)}>{children}</div>;
}

export function CaseBlock({ children }: { children: ReactNode }) {
    return <div className="pui-cs-block">{children}</div>;
}

/** A panel link; the small label shows where it goes */
export function CtaLink({ href, label, kicker }: { href: string; label: ReactNode; kicker?: ReactNode }) {
    const internal = href.startsWith("/") || href.startsWith("#");
    const host = internal ? "" : new URL(href).host.replace(/^www\./, "");
    return (
        <a className="pui-cs-cta" href={href} {...(internal ? {} : { target: "_blank", rel: "noopener" })}>
            <span>
                <span className="pui-cs-kicker">{kicker ?? host}</span>
                <span className="pui-cs-cta-title">{label}</span>
            </span>
        </a>
    );
}

export function Rollout({ phases }: { phases: { label: ReactNode; title: ReactNode; description: ReactNode }[] }) {
    return (
        <div className="pui-cs-rollout">
            {phases.map((p, i) => (
                <div key={i} className="pui-cs-rollout-card">
                    <p className="pui-cs-rollout-phase">{p.label}</p>
                    <p><strong>{p.title}</strong><br />{p.description}</p>
                </div>
            ))}
        </div>
    );
}

type PagerLink = { href: string; label: ReactNode; kicker?: ReactNode };

export function CasePager({ prev, next }: { prev?: PagerLink; next?: PagerLink }) {
    return (
        <nav className="pui-cs-pager" aria-label="More case studies">
            {prev && (
                <a className="pui-cs-next" href={prev.href}>
                    <span className="pui-cs-kicker">{prev.kicker ?? "Previous"}</span>
                    <span className="pui-cs-next-title">{prev.label}</span>
                </a>
            )}
            {next && (
                <a className="pui-cs-next pui-cs-next--next" href={next.href}>
                    <span className="pui-cs-kicker">{next.kicker ?? "Next"}</span>
                    <span className="pui-cs-next-title">{next.label}</span>
                </a>
            )}
        </nav>
    );
}

.pui-cs {
    display: grid;
    grid-template-columns: var(--rail-w) minmax(0, 1fr);
    gap: clamp(2rem, 5vw, 5rem);
    max-width: 75rem;
    margin: 0 auto;
    padding: var(--s-7) clamp(1rem, 4vw, 3rem) 0;
    font-family: var(--font-serif);
}

.pui-cs-main {
    min-width: 0;
    max-width: 52rem;
    counter-reset: pui-section pui-fig;
}

.pui-cs-kicker {
    display: block;
    margin: 0;
    font-family: var(--font-serif);
    font-size: var(--fs-kicker);
    font-weight: 400;
    font-style: normal;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: var(--text-tertiary);
}

/* ----- Rail ----- */
.pui-cs-rail {
    position: sticky;
    top: var(--rail-top, 8rem);
    align-self: start;
    display: flex;
    flex-direction: column;
    height: calc(100vh - var(--rail-top, 8rem) - var(--s-6));
}

.pui-cs-back {
    display: inline-block;
    margin-bottom: var(--s-6);
    font-size: var(--fs-1);
    font-style: italic;
    color: var(--text-tertiary);
    text-decoration: none;
}

.pui-cs-rail-title {
    margin: var(--s-1) 0 var(--s-6);
    font-size: 1.05rem;
    line-height: 1.35;
    color: var(--text-primary);
}

.pui-cs-index {
    --node: 14px;
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    flex: 0 1 calc(var(--n, 6) * 4.5rem);
    min-height: 0;
    margin: 0;
    padding: 0;
    list-style: none;
}

.pui-cs-index::before,
.pui-cs-index .pui-cs-fill {
    content: "";
    position: absolute;
    left: calc(var(--node) / 2 - 1px);
    top: calc(var(--node) / 2);
    width: 2px;
}

.pui-cs-index::before {
    bottom: calc(var(--node) / 2);
    background: var(--rail-track);
}

.pui-cs-index .pui-cs-fill {
    background: var(--highlight);
}

.pui-cs-index li:not(.pui-cs-fill) {
    position: relative;
    height: var(--node);
}

.pui-cs-index a {
    display: flex;
    align-items: center;
    gap: var(--s-4);
    height: var(--node);
    text-decoration: none;
}

.pui-cs-index a::before {
    content: "";
    position: relative;
    flex: 0 0 var(--node);
    height: var(--node);
    border: 2px solid var(--rail-ring);
    border-radius: 50%;
    background: var(--rail-hole);
    /* Same three layers as the lit state, at zero, so the glow can swell in */
    box-shadow: 0 0 0 0 transparent, 0 0 0 0 transparent, 0 0 0 0 transparent;
    transition:
        background-color var(--dur-glow) var(--ease-out),
        border-color var(--dur-glow) var(--ease-out),
        box-shadow var(--dur-glow) var(--ease-out),
        filter var(--dur-glow) var(--ease-out);
}

.pui-cs-index a.is-passed::before {
    border-color: var(--highlight);
}

.pui-cs-index a.is-current::before {
    border-color: var(--highlight);
    background: var(--highlight);
    filter: var(--hover-blur);
    box-shadow:
        0 0 4px 1px var(--rail-core),
        0 0 12px 6px var(--rail-glow),
        0 0 30px 14px var(--rail-glow-soft);
}

.pui-cs-index-label {
    font-size: var(--fs-kicker);
    text-transform: uppercase;
    letter-spacing: 0.14em;
    line-height: 1.3;
    color: var(--text-tertiary);
    transition: color var(--dur-glow) var(--ease-out);
}

.pui-cs-index a.is-current .pui-cs-index-label {
    color: var(--text-primary);
}

.pui-cs-back,
.pui-cs-title a,
.pui-cs-cta,
.pui-cs-next {
    transition: filter var(--dur-1) var(--ease-out);
}

.pui-cs-back:hover,
.pui-cs-title a:hover,
.pui-cs-cta:hover,
.pui-cs-next:hover {
    filter: var(--hover-blur);
}

/* ----- Hero ----- */
.pui-cs-hero {
    margin-bottom: var(--s-6);
    padding-bottom: var(--s-7);
    border-bottom: 1px solid var(--hairline);
    scroll-margin-top: 6rem;
}

.pui-cs-hero-top {
    display: flex;
    justify-content: space-between;
    gap: var(--s-4);
}

.pui-cs-title {
    margin: var(--s-4) 0;
    font-family: var(--font-serif);
    font-size: var(--fs-display);
    font-weight: 400;
    line-height: 1.1;
    letter-spacing: -0.01em;
    color: var(--text-primary);
    text-wrap: balance;
}

.pui-cs-title a {
    color: inherit;
    text-decoration: none;
}

.pui-cs-sub {
    max-width: 44ch;
    margin: 0;
    font-size: 1.25rem;
    font-style: italic;
    line-height: 1.6;
    color: var(--text-secondary);
}

.pui-cs-tags {
    margin-top: var(--s-5);
}

.pui-cs-facts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
    gap: var(--s-5) var(--s-6);
    margin: var(--s-7) 0 0;
    padding: var(--s-5);
    background: linear-gradient(135deg, var(--facts-tint), var(--facts-tint-fade));
    border: 1px solid var(--hairline);
    border-radius: var(--r-sm);
}

.pui-cs-facts dt {
    margin-bottom: var(--s-2);
}

.pui-cs-facts dd {
    margin: 0;
    font-size: 0.95rem;
    line-height: 1.55;
    color: var(--text-primary);
}

/* ----- Sections ----- */
.pui-cs-section {
    margin-top: 7rem;
    scroll-margin-top: 6rem;
    counter-increment: pui-section;
}

.pui-cs-eyebrow {
    display: flex;
    gap: var(--s-3);
    margin: 0 0 var(--s-4);
    font-size: var(--fs-kicker);
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: var(--text-tertiary);
}

.pui-cs-num::before {
    content: counter(pui-section, decimal-leading-zero);
    color: var(--accent);
}

.pui-cs-heading {
    max-width: 26ch;
    margin: 0 0 var(--s-5);
    font-family: var(--font-serif);
    font-size: var(--fs-heading);
    font-weight: 400;
    line-height: 1.2;
    color: var(--text-primary);
    text-wrap: balance;
}

.pui-cs-prose :where(p, li) {
    max-width: 66ch;
    margin: 0 0 var(--s-4);
    font-family: var(--font-serif);
    font-size: 1.05rem;
    line-height: var(--lh);
    color: var(--text-secondary);
}

.pui-cs-prose :where(strong) {
    font-weight: 600;
    color: var(--text-primary);
}

.pui-cs-prose :where(h3) {
    margin: var(--s-6) 0 var(--s-3);
    font-family: var(--font-serif);
    font-size: 1.3rem;
    font-weight: 400;
    color: var(--text-primary);
}

.pui-cs-prose :where(a:not([class])) {
    color: var(--text-primary);
    text-decoration: underline;
    text-decoration-color: var(--hairline-strong);
    text-underline-offset: 3px;
}

/* ----- Figures, media, rows ----- */
.pui-cs-figure,
.pui-cs-block {
    margin: var(--s-6) 0;
}

.pui-cs-caption {
    max-width: 66ch;
    margin: var(--s-3) 0 0;
    font-family: var(--font-serif);
    font-size: 0.9rem;
    font-style: italic;
    line-height: 1.6;
    color: var(--text-tertiary);
}

.pui-cs-caption::before {
    counter-increment: pui-fig;
    content: "Fig. " counter(pui-fig, decimal-leading-zero);
    margin-right: var(--s-3);
    font-size: var(--fs-kicker);
    font-style: normal;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: var(--accent);
}

.pui-cs-media {
    width: 100%;
    margin: 0 auto;
    overflow: hidden;
    background: var(--glass);
    border: 1px solid var(--hairline);
}

.pui-cs-media img {
    display: block;
    width: 100%;
}

.pui-cs-media--sm { max-width: 420px; }
.pui-cs-media--md { max-width: 600px; }
.pui-cs-media--lg { max-width: 800px; }

.pui-cs-media--placeholder {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 260px;
    font-style: italic;
    color: var(--text-secondary);
    background: transparent;
    border: 1px dashed var(--dashed);
}

.pui-cs-row {
    display: grid;
    gap: var(--s-4);
    align-items: start;
}

.pui-cs-row > * { min-width: 0; }
.pui-cs-row--equal, .pui-cs-row--pair { grid-template-columns: 1fr 1fr; }
.pui-cs-row--flow { grid-template-columns: 0.85fr 1.15fr; }
.pui-cs-row--3 { grid-template-columns: repeat(3, 1fr); }
.pui-cs-row--quad { grid-template-columns: repeat(4, 1fr); }

/* ----- Rollout ----- */
.pui-cs-rollout {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    gap: var(--s-4);
}

.pui-cs-rollout-card {
    padding: var(--s-4) var(--s-5);
    background: var(--glass);
    border: 1px solid var(--hairline);
}

.pui-cs-rollout-card p {
    margin: 0;
    font-size: var(--fs-2);
    line-height: var(--lh);
    color: var(--text-secondary);
}

.pui-cs-rollout-card .pui-cs-rollout-phase {
    margin-bottom: var(--s-2);
    font-size: var(--fs-1);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--accent);
}

/* ----- CTA and pager ----- */
.pui-cs-cta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 66ch;
    margin: var(--s-5) 0;
    padding: var(--s-4) var(--s-5);
    text-decoration: none;
    background: var(--glass);
    border: 1px solid var(--hairline);
}

.pui-cs-cta .pui-cs-kicker {
    margin-bottom: var(--s-1);
}

.pui-cs-cta-title {
    display: block;
    font-size: 1.1rem;
    color: var(--text-primary);
}

.pui-cs-pager {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--s-6);
    margin: 8rem 0 0;
    padding: var(--s-6) 0 var(--s-7);
    border-top: 1px solid var(--hairline);
}

.pui-cs-next {
    display: block;
    text-decoration: none;
}

.pui-cs-next--next {
    grid-column: 2;
    text-align: right;
}

.pui-cs-next-title {
    display: block;
    margin-top: var(--s-3);
    font-size: var(--fs-heading);
    line-height: 1.2;
    color: var(--text-primary);
}

@media screen and (max-width: 1000px) {
    .pui-cs { grid-template-columns: minmax(0, 1fr); }
    .pui-cs-rail { display: none; }
    .pui-cs-main { max-width: none; }
}

@media screen and (max-width: 880px) {
    .pui-cs-row--equal, .pui-cs-row--flow, .pui-cs-row--3, .pui-cs-row--quad { grid-template-columns: 1fr; }
    .pui-cs-rollout { grid-auto-flow: row; }
}

@media screen and (max-width: 666px) {
    .pui-cs { padding: var(--s-6) var(--s-4) 0; }
    .pui-cs-section { margin-top: 4.5rem; }
    .pui-cs-facts { grid-template-columns: 1fr 1fr; margin-top: var(--s-6); }
    .pui-cs-sub { font-size: 1.1rem; }
    .pui-cs-pager { grid-template-columns: 1fr; }
    .pui-cs-next--next { grid-column: auto; }
}

import type { AnchorHTMLAttributes } from "react";
import { cx } from "./utils";
import "./scroll-mouse.css";

/** A mouse outline whose teal wheel slides down, then snaps back. Point href at what's below. */
export function ScrollMouse({ className, "aria-label": label = "Scroll down", ...props }: AnchorHTMLAttributes<HTMLAnchorElement>) {
    return <a className={cx("pui-scroll-mouse", className)} aria-label={label} {...props} />;
}

.pui-scroll-mouse {
    position: relative;
    display: block;
    width: 22px;
    height: 34px;
    border: 1.5px solid var(--mouse-line);
    border-radius: 12px;
    transition: filter var(--dur-1) var(--ease-out);
}

.pui-scroll-mouse:hover,
.pui-scroll-mouse:focus-visible {
    filter: var(--hover-blur);
}

.pui-scroll-mouse::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 6px;
    width: 3px;
    height: 7px;
    margin-left: -1.5px;
    border-radius: 2px;
    background: var(--accent);
    animation: pui-mouse-wheel 1.8s ease-in-out infinite;
}

@keyframes pui-mouse-wheel {
    0% { transform: translateY(0); }
    60%, 80% { transform: translateY(10px); }
    80.01%, 100% { transform: translateY(0); }
}

"use client";
import { useEffect } from "react";

// A small fire crackle on every click of something interactive.
// Synthesized with Web Audio (filtered noise + a few pops), so there's no sound file.
const INTERACTIVE = 'a[href], button, input, select, textarea, label, summary, [role="button"], [onclick], [tabindex]:not([tabindex="-1"])';

let ctx: AudioContext | null = null;
let noise: AudioBuffer | null = null;

function burst(t: number, dur: number, freq: number, q: number, gain: number, type: BiquadFilterType) {
    const src = ctx!.createBufferSource();
    src.buffer = noise;
    src.playbackRate.value = 0.8 + Math.random() * 0.4;
    const filter = ctx!.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const env = ctx!.createGain();
    env.gain.setValueAtTime(0.0001, t);
    env.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.01, dur / 4));
    env.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(env).connect(ctx!.destination);
    src.start(t, Math.random() * 0.5, dur + 0.05);
}

/** Play one crackle now */
export function crackle(volume = 1) {
    if (!ctx) {
        const AC = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!AC) return;
        ctx = new AC();
        noise = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
        const data = noise.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    }
    if (ctx.state === "suspended") ctx.resume();
    const t = ctx.currentTime + 0.005;
    // Soft whoosh of the flame catching, then a few crackles scattered over it
    burst(t, 0.28, 600, 0.7, 0.12 * volume, "lowpass");
    const pops = 3 + Math.floor(Math.random() * 3);
    for (let i = 0; i < pops; i++) {
        burst(t + Math.random() * 0.22, 0.015 + Math.random() * 0.02, 1800 + Math.random() * 2500, 3, (0.18 + Math.random() * 0.12) * volume, "bandpass");
    }
}

/** Crackle on every click of a link, button, field or anything with cursor: pointer */
export function useFireCrackle(enabled = true, volume = 1) {
    useEffect(() => {
        if (!enabled) return;
        const onDown = (e: PointerEvent) => {
            if (e.button !== 0 || !(e.target instanceof Element)) return;
            if (e.target.closest(INTERACTIVE) || getComputedStyle(e.target).cursor === "pointer") crackle(volume);
        };
        document.addEventListener("pointerdown", onDown, { capture: true, passive: true });
        return () => document.removeEventListener("pointerdown", onDown, { capture: true });
    }, [enabled, volume]);
}

/** Drop once anywhere in the app to turn the crackle on */
export function FireCrackle({ enabled = true, volume = 1 }: { enabled?: boolean; volume?: number }) {
    useFireCrackle(enabled, volume);
    return null;
}

import type { HTMLAttributes, ImgHTMLAttributes } from "react";
import { cx } from "./utils";
import "./shimmer.css";

/** Text that shimmers teal and white on hover. Use sparingly: one per page. */
export function Shimmer({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
    return <span className={cx("pui-shimmer", className)} {...props} />;
}

/** An unframed image whose edges dissolve into the black */
export function FeatherImage({ className, alt = "", ...props }: ImgHTMLAttributes<HTMLImageElement>) {
    return <img className={cx("pui-feather", className)} alt={alt} {...props} />;
}

.pui-shimmer {
    cursor: pointer;
}

.pui-shimmer:hover,
a:hover > .pui-shimmer,
a:focus-visible > .pui-shimmer {
    background: linear-gradient(45deg, var(--accent), var(--highlight), var(--accent));
    background-size: 200%;
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    animation: pui-shimmer 2s infinite linear;
}

@keyframes pui-shimmer {
    0% { background-position: 0%; }
    100% { background-position: 100%; }
}

.pui-feather {
    display: block;
    -webkit-mask-image: var(--feather-mask);
    -webkit-mask-composite: source-in;
    mask-image: var(--feather-mask);
    mask-composite: intersect;
}
